def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    total_alive = 1 + len(alive_opponents)
    affordable_cap = max(0.0, min(float(budget), float(DAILY_SALARY)))

    if affordable_cap <= 0:
        return 0.0

    units_available = float(supply) / float(WATER_REQ)
    scarcity = total_alive - units_available

    prev_bids = []
    desperate_opp = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            desperate_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 2 or no_water_days >= 1
    critical = hp <= 1 or no_water_days >= 2

    if critical:
        bid = min(affordable_cap, DAILY_SALARY * 0.98)
        return float(max(0.0, bid))

    if emergency:
        target = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
        bid = min(affordable_cap, target)
        return float(max(0.0, bid))

    if len(alive_opponents) == 0:
        return float(min(affordable_cap, DAILY_SALARY * 0.35))

    if scarcity <= 0:
        base = DAILY_SALARY * 0.34
    elif scarcity <= 0.5:
        base = DAILY_SALARY * 0.46
    elif scarcity <= 1.0:
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.68

    if highest_prev >= DAILY_SALARY * 0.9:
        if hp >= 4 and no_water_days == 0:
            bid = min(affordable_cap, DAILY_SALARY * 0.28)
        else:
            bid = min(affordable_cap, DAILY_SALARY * 0.88)
        return float(max(0.0, bid))

    if prev_bids:
        if highest_prev < DAILY_SALARY * 0.75:
            base = max(base, highest_prev + 1.5)
        else:
            base = max(base, avg_prev + 1.0)

    if desperate_opp >= max(1, len(alive_opponents) // 2):
        base += 4.0

    if budget < DAILY_SALARY * 2:
        base = min(base, DAILY_SALARY * 0.62)

    bid = min(affordable_cap, base)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, bid to meet requirement with some slack
    if not alive_opps:
        bid = min(my_status.get('budget', 0.0), DAILY_SALARY * 0.6)
        return bid

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    yesterday_states = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            yesterday_bids.append(b)
            yesterday_states.append((opp, b, prev))

    # If we have no yesterday bids, fall back to conservative-mid bid
    if not yesterday_bids:
        # If low HP or many no-water days, increase bid
        hp = my_status.get('hp', 0)
        no_water_days = my_status.get('no_water_days', 0)
        if hp <= 2 or no_water_days >= 2:
            return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.9)
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)
    lowest_prev_bid = min(yesterday_bids)

    hp = my_status.get('hp', 0)
    no_water_days = my_status.get('no_water_days', 0)
    budget = my_status.get('budget', 0.0)

    # Estimate how many water units are likely to be available (for urgency calibration)
    # Use explicit int() to avoid float index issues (even though we don't index arrays)
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ else 0

    # Determine pressure level from opponent bids
    # If they bid very high, they likely expect to be outbid or are desperate.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.55) or (highest_prev_bid - lowest_prev_bid >= DAILY_SALARY * 0.2)

    # Core bidding policy
    if high_pressure:
        # If we're healthy, still bid to contest; if we're low HP, bid harder.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.75
        # If supply is tight (few units), increase slightly
        if approx_units <= 1:
            target += DAILY_SALARY * 0.1
        return min(budget, target)

    if medium_pressure:
        # Bid enough to stay competitive but avoid overpaying.
        # Also react to whether opponents previously bid clustered near our daily salary.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.7
        else:
            # Slightly above the median of yesterday bids if available
            sorted_bids = sorted(yesterday_bids)
            mid_idx = int(len(sorted_bids) // 2)
            medianish = sorted_bids[mid_idx]
            target = max(DAILY_SALARY * 0.55, medianish + 5.0)
        return min(budget, target)

    # Low pressure: bid moderately; if we're already suffering, increase.
    if hp <= 2 or no_water_days >= 2:
        return min(budget, DAILY_SALARY * 0.85)

    # Late in episode: increase bid to avoid endgame starvation.
    # day is 0-indexed or 1-indexed unknown; use relative position to 10 days.
    try:
        remaining_days = 10 - int(day)
    except Exception:
        remaining_days = 5

    if remaining_days <= 3:
        return min(budget, DAILY_SALARY * 0.65)

    return min(budget, DAILY_SALARY * 0.5)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # --- Survival Logic --- 
    # If I'm in critical condition (low HP or missed water yesterday), bid very aggressively
    if my_status['no_water_days'] >= 1 or my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)
    # If HP is low but not critical, bid high
    if my_status['hp'] <= 4:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    # --- No Opponents Logic ---
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1) # Bid very low if no competition

    # --- Analyze Yesterday's Opponent Bids ---
    yesterday_opponent_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_opponent_bids.append(prev['bid'])

    highest_prev_opponent_bid = 0
    if yesterday_opponent_bids:
        highest_prev_opponent_bid = max(yesterday_opponent_bids)

    # --- Supply and Competition Logic ---
    supply = day_context['supply']
    current_bid = DAILY_SALARY * 0.5 # Default moderate bid

    # Calculate how much water is available per active player if split
    # Note: Using float division is fine here as it's not an index.
    water_per_player_if_split = supply / (num_alive_opponents + 1) 

    # If supply is very scarce (not enough for everyone to get their WATER_REQ)
    if supply < WATER_REQ * (num_alive_opponents + 1):
        if water_per_player_if_split < WATER_REQ: # Not enough for everyone to get full water
            # Competition is high. Try to outbid yesterday's highest, or bid a high percentage.
            if highest_prev_opponent_bid > 0:
                current_bid = max(DAILY_SALARY * 0.7, highest_prev_opponent_bid + 5)
            else:
                current_bid = DAILY_SALARY * 0.75
        else: # Enough water for everyone to get some, but not all full WATER_REQ
            if highest_prev_opponent_bid > 0:
                current_bid = max(DAILY_SALARY * 0.6, highest_prev_opponent_bid + 3)
            else:
                current_bid = DAILY_SALARY * 0.65
    else: # Supply is abundant (enough for everyone to get their WATER_REQ, or more)
        # Can afford to bid lower.
        if highest_prev_opponent_bid > 0:
            if highest_prev_opponent_bid < DAILY_SALARY * 0.4: # If opponents bid very low
                current_bid = max(DAILY_SALARY * 0.3, highest_prev_opponent_bid + 1) # Bid slightly above
            else: # Opponents bid moderate even with abundant supply, be cautious but still try to save
                current_bid = max(DAILY_SALARY * 0.4, highest_prev_opponent_bid + 2)
        else:
            current_bid = DAILY_SALARY * 0.4 # Default low bid for abundant supply

    # Final bid adjustment and budget check
    final_bid = min(my_status['budget'], current_bid)

    # Ensure bid is at least 1 if budget allows and not 0, to participate.
    if final_bid <= 0 and my_status['budget'] > 0:
        final_bid = 1
    elif final_bid <= 0: # If budget is 0, then bid 0.
        final_bid = 0

    return final_bid

